<?php
declare(strict_types=1);
require __DIR__.'/app/bootstrap.php';
$userId=require_auth();$pdo=db();$service=new TripItineraryIntelligenceService($pdo);$tripId=(int)($_GET['id']??$_POST['trip_id']??0);$date=(string)($_GET['date']??$_POST['date']??'');$error='';
if($tripId<1){http_response_code(400);exit('Trip is required.');}
try{$access=$service->access($userId,$tripId);}catch(Throwable){http_response_code(404);exit('Trip not found.');}
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();
    try{
        if(!$service->ready())throw new RuntimeException('Run System Upgrade before editing Complete Itinerary Intelligence.');$action=(string)($_POST['action']??'');
        if($action==='save_item_timing'){$service->saveItemTiming($userId,$tripId,(int)($_POST['item_id']??0),$_POST);flash('success','Itinerary timing saved and the trip was rechecked for downstream conflicts.');}
        elseif($action==='apply_order'){$count=$service->applySuggestedOrder($userId,$tripId,$date);flash('success',$count.' flexible itinerary item'.($count===1?'':'s').' sequenced. Fixed reservations were not moved.');}
        elseif($action==='save_preferences'){$service->savePreferences($userId,$tripId,$_POST);flash('success','Timing and buffer preferences saved.');}
        elseif($action==='refresh'){$service->snapshot($userId,$tripId,$date?:null,true);flash('success','Itinerary intelligence recalculated from saved trip facts. No provider was contacted.');}
        else throw new InvalidArgumentException('Unknown itinerary action.');
        redirect('trip-itinerary.php?id='.$tripId.($date!==''?'&date='.rawurlencode($date):''));
    }catch(Throwable $e){$error=$e->getMessage();}
}
try{$snapshot=$service->snapshot($userId,$tripId,$date?:null,true);}catch(Throwable $e){$error=$e->getMessage();$snapshot=['ready'=>false,'trip'=>['name'=>'Trip','destination_name'=>''],'access'=>$access,'selected_date'=>$date?:date('Y-m-d'),'dates'=>[],'timeline'=>[],'issues'=>[],'gaps'=>[],'unscheduled'=>[],'summary'=>[],'preferences'=>$service->preferences($tripId),'map_points'=>[]];}
$trip=$snapshot['trip'];$access=$snapshot['access']??$access;$canPlan=!empty($access['can_plan']);$date=(string)$snapshot['selected_date'];$success=flash('success');$title='Itinerary — '.(string)$trip['name'];$pageStyles=['assets/trip-itinerary-intelligence.css'];
function iti_time(?string $value): string{return $value&&strtotime($value)?date('H:i',strtotime($value)):'';}
function iti_type(string $type): string{return ucwords(str_replace('_',' ',$type));}
require __DIR__.'/partials/header.php';
?>
