<header class="trip-intelligence-head"><div><a class="back-link" href="<?=e(app_url('dream-trip.php?id='.$tripId.'&workspace=timeline&itinerary_date='.rawurlencode($date)))?>">← Trip timeline workspace</a><div class="eyebrow">Complete Itinerary Intelligence · <?=e(ucwords(str_replace('_',' ',(string)$access['role'])))?></div><h1><?=e((string)$trip['name'])?></h1><p><?=e((string)($trip['destination_name']?:'Destination TBD'))?> · fixed bookings + flexible plan + transfer intelligence</p></div><div class="trip-intelligence-head-actions"><a class="button secondary small" href="<?=e(app_url('travel-mode.php?id='.$tripId.'&date='.rawurlencode($date)))?>">Travel Mode</a><a class="button secondary small" href="<?=e(app_url('trip-inbox.php?trip='.$tripId))?>">Trip Inbox</a><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="trip_id" value="<?=$tripId?>"><input type="hidden" name="date" value="<?=e($date)?>"><input type="hidden" name="action" value="refresh"><button class="button primary small" type="submit">Recalculate</button></form></div></header>
<?php if($success):?><div class="alert success"><?=e($success)?></div><?php endif;?><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?>
