<?php if(!empty($snapshot['issues'])):?><div class="vb-itinerary-issues"><?php foreach($snapshot['issues'] as $issue):?><article class="severity-<?=e((string)$issue['severity'])?>"><span><?=e(strtoupper((string)$issue['severity']))?></span><div><strong><?=e((string)$issue['title'])?></strong><p><?=e((string)$issue['body'])?></p></div></article><?php endforeach;?></div><?php endif;?>
<div class="vb-itinerary-timeline"><?php foreach($snapshot['timeline'] as $entry):?><article class="vb-itinerary-row <?=!empty($entry['fixed'])?'fixed':'flexible'?>"><div class="vb-itinerary-time"><strong><?=e((string)$entry['time_label'])?></strong><span><?=!empty($entry['fixed'])?'Fixed':'Flexible'?></span></div><div class="vb-itinerary-marker"><i></i></div><div class="vb-itinerary-copy"><div class="vb-itinerary-title"><strong><?=e((string)$entry['title'])?></strong><span><?=e(iti_type((string)$entry['type']))?></span></div><?php $loc=trim((string)$entry['location']);$addr=trim((string)$entry['address']);if($loc||$addr):?><p><?=e($loc.($loc&&$addr?' · ':'').$addr)?></p><?php endif;?><?php if(!empty($entry['transition'])):?><small><?=e((string)$entry['transition']['label'])?><?php if($entry['leave_by']):?> · Leave by <?=e(date('g:i A',strtotime((string)$entry['leave_by'])) )?><?php endif;?><?php if($entry['arrive_by']):?> · Target arrival <?=e(date('g:i A',strtotime((string)$entry['arrive_by'])))?><?php endif;?></small><?php elseif($entry['arrive_by']):?><small>Target arrival <?=e(date('g:i A',strtotime((string)$entry['arrive_by'])))?></small><?php endif;?></div></article><?php endforeach;?><?php if(empty($snapshot['timeline'])):?><div class="vb-itinerary-empty"><strong>No timed plan for this day.</strong><span>Assign itinerary ideas to <?=e(date('M j',strtotime($date)))?> or import a confirmed reservation.</span></div><?php endif;?></div>
<?php if(!empty($snapshot['gaps'])):?><div class="vb-itinerary-gap-row"><?php foreach($snapshot['gaps'] as $gap):?><a href="<?=e(app_url('local-concierge.php?id='.$tripId))?>"><strong><?=e((string)$gap['title'])?> · <?=round((int)$gap['minutes']/60,1)?>h</strong><span><?=e((string)$gap['body'])?> Ask Local Agent for ideas.</span></a><?php endforeach;?></div><?php endif;?>
