ocation_name" value="<?=e((string)$entry['location'])?>" placeholder="Museum, restaurant, hotel…"></label><label class="wide">Address<input class="input" name="location_address" value="<?=e((string)$entry['address'])?>"></label><label>Latitude<input class="input" inputmode="decimal" name="latitude" value="<?=e($entry['latitude']!==null?(string)$entry['latitude']:'')?>"></label><label>Longitude<input class="input" inputmode="decimal" name="longitude" value="<?=e($entry['longitude']!==null?(string)$entry['longitude']:'')?>"></label><div class="form-actions"><button class="button primary small" type="submit">Save & recheck</button></div></form><?php else:?><p class="muted">Your <?=e(ucwords(str_replace('_',' ',(string)$access['role'])))?> role can view this timing plan but cannot edit the shared itinerary.</p><?php endif;?></article>
